import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from '../api/axios';
import { FaMapMarkerAlt, FaCalendarAlt, FaTrash, FaClipboardList } from 'react-icons/fa';

function Events() {
  const [events, setEvents] = useState([]);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const res = await axios.get('/events');
        setEvents(res.data);
      } catch (err) {
        console.error('Fetch Events Error:', err);
        setError('Failed to fetch events');
      }
    };

    const checkAdmin = () => {
      const token = localStorage.getItem('token');
      if (token) {
        try {
          const decoded = JSON.parse(atob(token.split('.')[1]));
          if (decoded.role === 'admin') {
            setIsAdmin(true);
          }
        } catch (err) {
          console.error('Token decode error:', err);
        }
      }
    };

    fetchEvents();
    checkAdmin();
  }, []);

  const handleRegister = async (eventId) => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Login required to register for events.');
      return;
    }

    try {
      const res = await axios.post(
        '/registration/register-event',
        { eventId },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      setMessage(res.data.message || 'Registered successfully');
      setError('');
    } catch (err) {
      console.error('Registration Error:', err);
      setMessage('');
      setError(err.response?.data?.message || 'Registration failed');
    }
  };

  const handleDelete = async (eventId) => {
    const confirmDelete = window.confirm('Are you sure you want to delete this event?');
    if (!confirmDelete) return;

    try {
      const token = localStorage.getItem('token');
      await axios.delete(`/events/${eventId}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      setEvents(events.filter((e) => e._id !== eventId));
      setMessage('Event deleted successfully');
      setError('');
    } catch (err) {
      console.error('Delete Event Error:', err);
      setMessage('');
      setError('Failed to delete event');
    }
  };

  return (
    <div
      style={{
        backgroundImage: `url('https://images.unsplash.com/photo-1524995997946-a1c2e315a42f')`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        minHeight: '100vh',
        width: '100%',
        padding: '2rem',
        overflow: 'auto',
      }}
    >
      <h2 className="text-center text-white mb-4">🎉 Upcoming Events</h2>

      {message && <div className="alert alert-success bg-success text-white">{message}</div>}
      {error && <div className="alert alert-danger bg-danger text-white">{error}</div>}

      {events.length === 0 ? (
        <p className="text-center text-white">No events found</p>
      ) : (
        <div className="row">
          {events.map((event) => (
            <div key={event._id} className="col-md-4 mb-4">
              <div className="card bg-dark text-white bg-opacity-75 h-100">
                <div className="card-body">
                  <h5 className="card-title">{event.title}</h5>
                  <p className="card-text">{event.description}</p>
                  <p><FaCalendarAlt className="me-2" /><strong>Date:</strong> {new Date(event.date).toLocaleDateString()}</p>
                  <p><FaMapMarkerAlt className="me-2" /><strong>Location:</strong> {event.location}</p>
                  <p><small>By: {event.createdBy?.name || 'Admin'}</small></p>

                  <button
                    className="btn btn-light mt-2"
                    onClick={() => handleRegister(event._id)}
                  >
                    Register
                  </button>

                  {isAdmin && (
                    <>
                      <button
                        className="btn btn-outline-light mt-2 ms-2"
                        onClick={() => navigate(`/event-registrations/${event._id}`)}
                      >
                        <FaClipboardList className="me-1" /> View Registrations
                      </button>

                      <button
                        className="btn btn-danger mt-2 ms-2"
                        onClick={() => handleDelete(event._id)}
                      >
                        <FaTrash className="me-1" /> Delete
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Events;
